# Homebrew formula for systimus-proxy. Generated by
# .github/workflows/proxy-release.yml on every `proxy-v*` tag.
# Do not hand-edit in the tap repo — edit the renderer in the systimus repo.
class SystimusProxy < Formula
  desc "Local HTTPS passthrough for Claude Code that captures exact AI spend"
  homepage "https://systimus.io"
  version "0.4.2"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/systimus/proxy-releases/releases/download/v0.4.2/systimus-proxy-0.4.2-darwin-arm64.tar.gz"
      sha256 "b5645c125fead0f874c852ab7de874f7ef994618695859486ed2a7d64ed10bdd"
    end
    on_intel do
      url "https://github.com/systimus/proxy-releases/releases/download/v0.4.2/systimus-proxy-0.4.2-darwin-amd64.tar.gz"
      sha256 "2933e68b369c89c50345a94ecfb1f08ce75f688c61195df17aea034b3064da23"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/systimus/proxy-releases/releases/download/v0.4.2/systimus-proxy-0.4.2-linux-arm64.tar.gz"
      sha256 "f55d6f09e4aa874a62c46fb157fbe7dded903a9f38f09d07b03302c30ec928e1"
    end
    on_intel do
      url "https://github.com/systimus/proxy-releases/releases/download/v0.4.2/systimus-proxy-0.4.2-linux-amd64.tar.gz"
      sha256 "944874ea625e03a1083ff37263562e4138d4ab0042f6a094cbfd2ed6ee47dd44"
    end
  end

  def install
    bin.install "systimus-proxy"
  end

  # Managed background service: `brew services start systimus-proxy`.
  # The binary reads its API key from ~/.systimus/proxy/config.toml (written by
  # `systimus-proxy setup`), so the generated plist carries NO secrets and no
  # user-specific paths — the binary resolves its own config at runtime.
  service do
    run [opt_bin/"systimus-proxy"]
    keep_alive crashed: true
    log_path var/"log/systimus-proxy.log"
    error_log_path var/"log/systimus-proxy-error.log"
    working_dir HOMEBREW_PREFIX
  end

  def caveats
    <<~EOS
      First-time setup (writes your API key and wires your shell, once):
        systimus-proxy setup

      Run it as a managed background service (restarts on crash, starts on login):
        brew services start systimus-proxy

      `setup` offers to add this to your shell profile; to wire it by hand:
        eval "$(systimus-proxy shellenv)"      # fish: systimus-proxy shellenv | source

      Run `systimus-proxy setup` before starting the service — without a config
      file the proxy exits on launch and the service won't stay up. Diagnostics:
        tail -f #{HOMEBREW_PREFIX}/var/log/systimus-proxy-error.log

      `brew uninstall` leaves your config and spooled events in place. To remove
      them (flushes any pending spend events first):
        systimus-proxy purge
    EOS
  end

  test do
    assert_match(/\d+\.\d+\.\d+|dev/, shell_output("#{bin}/systimus-proxy --version"))
  end
end
